// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    // Fuzzed parameters: depositor (actor) and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep depositor non-zero and amount reasonably bounded to avoid overflow in vm.deal
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund depositor so they can send ETH
        vm.deal(depositor, amount);

        // depositor sends ETH to contract via fallback (which records balances[msg.sender] += msg.value)
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        // Sanity: the contract should now hold `amount` and its public getter for balances reports amount
        uint256 beforeContractBalance = address(c).balance;
        uint256 recorded = c.balances(depositor);
        // both should equal amount
        assertTrue(beforeContractBalance == amount);
        assertTrue(recorded == amount);

        // Now call withdraw as the depositor. Capture whether the external call succeeded (try/catch wrapper)
        bool ok;
        vm.prank(depositor);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a correct implementation, withdraw transfers `amount` out and sets c.balances(depositor)==0 and address(c).balance==0.
        // For the mutant that calls msg.sender.call{value:0} the contract balance will remain >0 and balances(depositor) may still be non-zero.
        // We assert the universal property that if withdraw succeeded then contract balance is strictly less than the prior contract balance
        // (i.e., some value left the contract). The mutant that sends value 0 but returns success will violate this for the same successful path.

        if (ok) {
            // When withdraw returns successfully, the reference always reduces address(c).balance compared to beforeContractBalance
            // (it should send out the recorded amount). This must hold for all inputs in the correct contract and is violated by the mutant for some inputs.
            assertTrue(address(c).balance < beforeContractBalance);
        } else {
            // If withdraw reverted, still the reference contract never reverts in this scenario (it should succeed),
            // but to avoid excluding valid fuzz inputs we simply assert a trivial true here — however to satisfy the requirement
            // that the single assertion reads c, we assert that balances mapping remains equal to recorded (state unchanged on revert).
            assertTrue(c.balances(depositor) == recorded);
        }
    }
}

// No adversarial helper needed because behavior difference is observable via address(c).balance and c.balances getter.
